try (ServerSocket ss = new ServerSocket(12345)) {
    System.out.println("[서버] 듣는다 " + ss.getLocalSocketAddress());
    try (Socket s = ss.accept()) {              // 여기서 멈춘다
        System.out.println("[서버] 상대  = " + s.getRemoteSocketAddress());
        // s.getInputStream() / s.getOutputStream() 으로 주고받는다 (7.3절)
    }
}

try (Socket s = new Socket("127.0.0.1", 12345)) {
    System.out.println("[클라] 붙었다. 내 쪽 = " + s.getLocalSocketAddress());
    System.out.println("[클라] 상대   = " + s.getRemoteSocketAddress());
}

// new Socket(host, port) 이 곧 connect 다 — 생성자에서 붙는다.
// 타임아웃을 주려면 new Socket() 뒤에 connect(addr, ms) 를 부른다(7.6절).
